/**
 * Keep control-plane Temporal calendars aligned with authored
 * `agent/schedules/*`. Upsert current names and delete ones that disappeared
 * since the last successful sync (persisted under the engine state root).
 */
import { mkdir, readFile, writeFile } from "node:fs/promises";
import { dirname } from "node:path";
export const PLATFORM_SCHEDULE_CATALOG_FILENAME = "platform-schedule-names.json";
export async function syncHostedPlatformSchedules(args) {
    const previous = await readScheduleCatalog(args.catalogPath);
    const currentNames = args.schedules.map((schedule) => schedule.name);
    const currentSet = new Set(currentNames);
    const failedDeletes = [];
    for (const name of previous) {
        if (currentSet.has(name)) {
            continue;
        }
        try {
            await args.timers.deleteSchedule(name);
        }
        catch (error) {
            failedDeletes.push(name);
            args.logger(`[bdk] platform timer delete failed for schedule "${name}": ${error instanceof Error ? error.message : String(error)}`);
        }
    }
    for (const schedule of args.schedules) {
        try {
            await args.timers.upsertSchedule({
                name: schedule.name,
                cron: schedule.cron,
            });
        }
        catch (error) {
            args.logger(`[bdk] platform timer upsert failed for schedule "${schedule.name}": ${error instanceof Error ? error.message : String(error)}`);
        }
    }
    // Keep failed removals in the catalog so the next boot retries them.
    await writeScheduleCatalog(args.catalogPath, [...new Set([...currentNames, ...failedDeletes])]);
}
async function readScheduleCatalog(catalogPath) {
    try {
        const parsed = JSON.parse(await readFile(catalogPath, "utf8"));
        if (!Array.isArray(parsed)) {
            return [];
        }
        return parsed.filter((entry) => typeof entry === "string");
    }
    catch {
        return [];
    }
}
async function writeScheduleCatalog(catalogPath, names) {
    await mkdir(dirname(catalogPath), { recursive: true });
    await writeFile(catalogPath, `${JSON.stringify(names)}\n`, "utf8");
}
